def entries():
    out=[]; seen=set()
    for lst,t,k in [(SAVOURY_DINNERS,'v','d'),(SWEET_DISHES,'s','p'),(VEG_AND_SAVOURY,'v','f'),(FRUIT,'s','f')]:
        for n in lst:
            n=n.strip()
            if n.lower() in seen: continue
            seen.add(n.lower()); out.append([n,t,k])
    return out
